import{_ as t,o as s,c as i,ag as a}from"./chunks/framework.CVaJrGn7.js";const u=JSON.parse('{"title":"Accessibility","description":"What GuideFlow does for screen-reader and keyboard users out of the box, what it deliberately does not do, and what you still have to do yourself.","frontmatter":{"description":"What GuideFlow does for screen-reader and keyboard users out of the box, what it deliberately does not do, and what you still have to do yourself.","keywords":"product tour accessibility, WCAG tour library, screen reader onboarding, keyboard accessible tour, prefers-reduced-motion","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/guide/accessibility"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/guide/accessibility"}],["meta",{"property":"og:title","content":"Accessibility — GuideFlow.js"}],["meta",{"property":"og:description","content":"What GuideFlow does for screen-reader and keyboard users out of the box, what it deliberately does not do, and what you still have to do yourself."}],["meta",{"name":"twitter:title","content":"Accessibility — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"What GuideFlow does for screen-reader and keyboard users out of the box, what it deliberately does not do, and what you still have to do yourself."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guide\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/guide/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Accessibility\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/guide/accessibility/\\"}]}"]]},"headers":[],"relativePath":"guide/accessibility.md","filePath":"guide/accessibility.md","lastUpdated":1785506067000}'),o={name:"guide/accessibility.md"};function n(r,e,d,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h1><p>A product tour sits on top of someone else&#39;s application and takes over the screen. That makes it one of the easiest things in a codebase to get wrong for keyboard and screen-reader users — and one of the most damaging, because it is the <em>first</em> thing a new user meets.</p><p>This page describes what the library does, what it deliberately does not do, and what is still on you.</p><div class="warning custom-block"><p class="custom-block-title">Verified by tooling, not yet by a person</p><p>Everything below is covered by automated tests — axe reports no critical or serious violations on an open popover, and the focus, keyboard and announcement behaviour is asserted in a real browser across Chromium, Firefox and WebKit.</p><p><strong>No manual screen-reader pass has been run.</strong> Automated checks catch structure, not usability. If accessibility is a requirement you have to sign off on, test with your own users and your own assistive technology before you rely on this.</p></div><h2 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>Cycles the popover&#39;s own controls. Focus cannot leave the dialog while a step is open.</td></tr><tr><td><code>→</code> / <code>↓</code></td><td>Next step</td></tr><tr><td><code>←</code> / <code>↑</code></td><td>Previous step</td></tr><tr><td><code>Escape</code></td><td>Ends the tour</td></tr></tbody></table><p>Focus moves into the popover when a step opens and returns to whatever held it before the tour started when the tour ends — the button the user clicked to start it, usually.</p><h3 id="arrow-keys-and-your-inputs" tabindex="-1">Arrow keys and your inputs <a class="header-anchor" href="#arrow-keys-and-your-inputs" aria-label="Permalink to &quot;Arrow keys and your inputs&quot;">​</a></h3><p>The arrow-key bindings live on <code>document</code>, so they could easily steal keystrokes from your app. They do not fire when the event targets:</p><ul><li>an <code>&lt;input&gt;</code>, <code>&lt;textarea&gt;</code> or <code>&lt;select&gt;</code></li><li>anything inside <code>[contenteditable]</code></li><li>an element with a widget <code>role</code> (<code>textbox</code>, <code>combobox</code>, <code>listbox</code>, <code>slider</code>, <code>menu</code>, <code>grid</code>, …)</li><li>a key that is part of an IME composition</li><li>a key held with <code>Ctrl</code>, <code>Alt</code> or <code>Meta</code></li><li>a key another handler has already called <code>preventDefault()</code> on</li></ul><p>This matters most for <a href="/GuideFlow/guide/spotlight-popover#click-through"><code>clickThrough</code></a> steps, which exist precisely so the user can type into the highlighted element.</p><p><code>Escape</code> is the exception: it fires from anywhere, including from inside a text field, because it is a keyboard user&#39;s only guaranteed way out of a modal.</p><h2 id="screen-readers" tabindex="-1">Screen readers <a class="header-anchor" href="#screen-readers" aria-label="Permalink to &quot;Screen readers&quot;">​</a></h2><p>The popover is a <code>role=&quot;dialog&quot;</code> with <code>aria-modal=&quot;true&quot;</code>. It takes its accessible name from the step title, and falls back to a translatable <code>dialogLabel</code> string when a step has no title. The body is wired up with <code>aria-describedby</code>, and both references are removed rather than left dangling when the corresponding content is absent.</p><p>Each step is announced through a polite live region. This is necessary because the popover element is <strong>reused</strong> between steps: a screen reader sees no new node, and moving focus reads only the focused button, not the step body. The region lives outside the popover so it survives the popover being removed.</p><p>The progress bar reports a step count, not a percentage:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">div</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;progressbar&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     aria-label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tour progress&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     aria-valuenow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-valuemin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-valuemax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     aria-valuetext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Step 2 of 4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>All four strings — <code>dialogLabel</code>, <code>progressLabel</code>, <code>stepOf</code>, and the button labels — go through the <a href="/GuideFlow/guide/i18n">i18n registry</a>, so they are announced in the user&#39;s language:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gf.i18n.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dialogLabel: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Visite guidée&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  progressLabel: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Progression&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  stepOf: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Étape {current} sur {total}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gf.i18n.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="reduced-motion" tabindex="-1">Reduced motion <a class="header-anchor" href="#reduced-motion" aria-label="Permalink to &quot;Reduced motion&quot;">​</a></h2><p>Under <code>prefers-reduced-motion: reduce</code> the library stops the popover entrance animation, the progress-bar and button transitions, the spotlight cutout&#39;s slide between targets, the hotspot beacon&#39;s pulse, and the smooth page scroll — the last two being the ones most likely to cause trouble, since one animates forever and the other moves the whole viewport.</p><p>Two of those are set from JavaScript and cannot be reached by a stylesheet, so this works whether or not you import <code>@guideflow/core/styles</code>.</p><h2 id="forced-colors-high-contrast" tabindex="-1">Forced colors / High Contrast <a class="header-anchor" href="#forced-colors-high-contrast" aria-label="Permalink to &quot;Forced colors / High Contrast&quot;">​</a></h2><p>Under <code>forced-colors: active</code> the popover, buttons and progress bar declare system colour keywords and let the OS map them. Opacity-based de-emphasis is reset, because opacity is not a colour and survives the forced palette. The spotlight cutout gains an outline, since the dimmed overlay itself disappears.</p><p>There is also an opt-in high-contrast theme independent of any OS setting:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data-gf-high-contrast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="right-to-left" tabindex="-1">Right-to-left <a class="header-anchor" href="#right-to-left" aria-label="Permalink to &quot;Right-to-left&quot;">​</a></h2><p>Set <code>dir=&quot;rtl&quot;</code> on your document and the popover follows. There is almost nothing RTL-specific in the stylesheet, and that is deliberate — flexbox and block layout already mirror themselves, so hand-written <code>[dir=&quot;rtl&quot;]</code> rules usually undo the browser&#39;s correct behaviour rather than fixing it.</p><p>Placement follows the CSS logical-property convention:</p><ul><li><code>top-start</code> / <code>bottom-start</code> align to the edge text <strong>begins</strong> at — the right edge in RTL</li><li><code>left</code> and <code>right</code> stay <strong>physical</strong>, so <code>placement: &#39;left&#39;</code> means left for everyone</li></ul><h2 id="contrast" tabindex="-1">Contrast <a class="header-anchor" href="#contrast" aria-label="Permalink to &quot;Contrast&quot;">​</a></h2><p>The default palette meets WCAG 2.1 AA. If you override the tokens, two constraints carry:</p><table tabindex="0"><thead><tr><th>Token</th><th>Constraint</th></tr></thead><tbody><tr><td><code>--gf-accent-color</code></td><td>≥ 4.5:1 against <code>--gf-accent-fg</code> — it is the primary button&#39;s background</td></tr><tr><td><code>--gf-muted-opacity</code></td><td>Raise it if you darken <code>--gf-popover-bg</code>; it de-emphasises real text</td></tr></tbody></table><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --gf-accent-color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#0f766e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  --gf-accent-fg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">#ffffff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="what-you-still-have-to-do" tabindex="-1">What you still have to do <a class="header-anchor" href="#what-you-still-have-to-do" aria-label="Permalink to &quot;What you still have to do&quot;">​</a></h2><p><strong>Give every target an accessible name.</strong> The tour points at your elements; it cannot describe them. A step highlighting an icon-only button announces the popover&#39;s text and nothing about what is being highlighted.</p><p><strong>Do not rely on the spotlight alone to convey meaning.</strong> It is a visual affordance. The step body has to say what the user is looking at.</p><p><strong>Write step text that stands on its own.</strong> &quot;Click here&quot; is meaningless to someone who cannot see where &quot;here&quot; is. Name the control.</p><p><strong>Test <code>clickThrough</code> steps by keyboard.</strong> If a step asks the user to interact with the page, make sure the thing they are meant to interact with is reachable by <code>Tab</code> from where focus is.</p><p><strong>The overlay is not <code>inert</code>.</strong> Background content stays focusable and in the accessibility tree. This is a deliberate trade: making it inert would break <code>clickThrough</code> entirely. If your tour never uses <code>clickThrough</code> and you want stricter isolation, apply <code>inert</code> to your app root yourself while a tour is running.</p><h2 id="custom-renderers" tabindex="-1">Custom renderers <a class="header-anchor" href="#custom-renderers" aria-label="Permalink to &quot;Custom renderers&quot;">​</a></h2><p>If you implement your own <a href="/GuideFlow/guide/spotlight-popover#custom-renderer"><code>RendererContract</code></a>, none of the above comes with it — the focus trap, live region and ARIA wiring all live in the default renderer. At minimum, reproduce:</p><ul><li>a focus trap and focus restoration around your dialog</li><li>a polite live region announcing each step, outside the element you reuse between steps</li><li>an accessible name on the dialog, and <code>aria-describedby</code> for the body</li><li><code>setI18n(registry)</code>, so your strings follow <code>gf.i18n.use(locale)</code></li></ul><p><code>@guideflow/react</code>&#39;s <code>GuidePopover</code> is a working reference for all four.</p>`,44)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
